@push('scripts')<script>$(function(){var t=$('#impairments-table'),x=$.fn.dataTable.render.text(),labels={DRAFT:'ร่าง',SUBMITTED:'รออนุมัติ',APPROVED:'อนุมัติแล้ว',POSTED:'ลงบัญชีแล้ว',CANCELLED:'ยกเลิก'},classes={DRAFT:'app-status-neutral',SUBMITTED:'app-status-info',APPROVED:'app-status-success',POSTED:'app-status-success',CANCELLED:'app-status-danger'},money=function(v){return Number(v||0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});};var table=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.status=$('#impairment-status').val();d.assessment_date_from=$('#impairment-date-from').val();d.assessment_date_to=$('#impairment-date-to').val();}},order:[[1,'desc']],buttons:[window.erpExcelButton(t)],columns:[{data:'document_number',render:x.display},{data:'assessment_date',render:function(v,z){return z==='display'?x.display(v?String(v).slice(0,10).split('-').reverse().join('/'):'-'):v;}},{data:'asset_label',render:x.display},{data:'carrying_amount',className:'text-end',render:function(v,z){return z==='display'?money(v):v;}},{data:'impairment_amount',className:'text-end',render:function(v,z){return z==='display'?money(v):v;}},{data:'status',render:function(v,z){return z==='display'?'<span class="badge '+(classes[v]||'app-status-neutral')+'">'+x.display(labels[v]||v)+'</span>':v;}},{data:'show_url',orderable:false,searchable:false,className:'text-end',render:function(v,z){return z==='display'?'<a class="btn btn-sm btn-outline-dark" href="'+x.display(v)+'">ดูรายละเอียด</a>':'';}}]}));$('#impairment-status,#impairment-date-from,#impairment-date-to').on('change',function(){table.ajax.reload();});$('#impairment-filter-reset').on('click',function(){$('#impairment-status,#impairment-date-from,#impairment-date-to').val('');table.ajax.reload();});});</script>@endpush
